SELECT 'knowledge_categories' AS entity, COUNT(*) AS seeded_rows
FROM "knowledge_categories"
WHERE "slug" IN ('maintenance', 'property-value', 'insurance', 'climate', 'safety', 'home-finance', 'buying-selling', 'seasonal-care')
UNION ALL
SELECT 'knowledge_tags', COUNT(*)
FROM "knowledge_tags"
WHERE "slug" IN ('roof-age', 'hvac-age', 'water-heater', 'plumbing', 'electrical', 'foundation', 'insulation', 'windows', 'appliances', 'curb-appeal', 'renovations', 'energy-efficiency', 'deferred-maintenance', 'neighborhood-trends', 'school-quality', 'marketability', 'climate-risk', 'water-damage', 'fire-risk', 'storm-risk', 'mold-risk', 'safety-hazards', 'maintenance-backlog', 'insurance-costs', 'maintenance-costs', 'resale-value', 'unexpected-repairs', 'aging-systems', 'premium-increases', 'first-time-homeowner', 'long-term-owner', 'seller', 'buyer', 'budget-conscious')
UNION ALL
SELECT 'product_tools', COUNT(*)
