WHERE "key" IN ('VALUE_TRACKER', 'BREAK_EVEN', 'BUDGET_PLANNER', 'CAPITAL_TIMELINE', 'COVERAGE_INTELLIGENCE', 'DIY', 'DO_NOTHING_SIMULATOR', 'DOCUMENT_VAULT', 'EMERGENCY_HELP', 'ENERGY_AUDIT', 'FINANCING', 'GUIDANCE_OVERVIEW', 'HOA_COMPLIANCE', 'HOME_BRIEFING', 'HOME_DIGITAL_TWIN', 'HOME_DIGITAL_WILL', 'HOME_EVENT_RADAR', 'HOME_HABIT_COACH', 'RENOVATION_RISK_ADVISOR', 'HOME_RISK_REPLAY', 'HOME_TIMELINE', 'INSPECTION_HUB', 'MATERIAL_SPECS', 'MORTGAGE_REFINANCE_RADAR', 'NEGOTIATION_SHIELD', 'NEIGHBORHOOD_CHANGE_RADAR', 'APPLIANCE_ORACLE', 'OWNERSHIP_COSTS', 'PERMITS', 'PLANT_ADVISOR', 'PRICE_FINALIZATION', 'PROJECT_TRACKER', 'PROPERTY_BRIEF', 'PROPERTY_TAX', 'QUOTE_COMPARISON', 'REPLACE_REPAIR', 'RESERVE_FUND', 'SAVINGS_BENEFITS', 'SELL_HOLD_RENT', 'SELLER_PREP', 'SERVICE_PRICE_RADAR', 'STATUS_BOARD', 'VISUAL_INSPECTOR', 'SEASONAL_MAINTENANCE', 'REPORT_PACK');
